#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

int average(int a, int b)
{
    return (a + b) / 2;
}

int last_char(const char *s)
{
    return s[strlen(s) - 1];
}

int main(void)
{
    printf("average(INT_MAX, INT_MAX) = %d\n", average(INT_MAX, INT_MAX));
    printf("last_char(\"abc\") = %c\n", last_char("abc"));
    return 0;
}
